import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep, vec2, length, float, abs, fract, max, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, PlaneGeometry, Shape, ShapeGeometry,
    ExtrudeGeometry, RingGeometry, DirectionalLight,
  } = ctx.THREE;

  const spec = config.intent?.visualSpec || {};
  const colors = spec.colors || {};
  const C_BG = colors.background || '#0b0b10';
  const C_SURF = colors.surface || '#16161d';
  const C_PAPER = colors.paper || '#e8ecf2';
  const C_INK = colors.ink || '#16161d';
  const C_ACCENT = colors.accent || '#ff2a38';
  const stops = colors.gradientStops || [{ at: 0, hex: '#14141a' }, { at: 1, hex: '#0b0b10' }];

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role, fallback) => {
    const it = items.find((i) => i.role === role);
    return it ? it.text : fallback;
  };
  const headlineTxt = byRole('headline', 'Your ledger is empty.');
  const bodyTxt = byRole('body', 'Commissioned pieces and saved references will appear here once you begin.');
  const ctaTxt = byRole('cta-label', 'BROWSE THE COLLECTION');

  const root = new Group();
  const disposables = [];
  const tweens = [];
  const primHandles = [];

  const track = (obj) => { disposables.push(obj); return obj; };

  function roundedRect(w, h, r) {
    const s = new Shape();
    const x = -w / 2, y = -h / 2;
    s.moveTo(x, y + r);
    s.lineTo(x, y + h - r);
    s.quadraticCurveTo(x, y + h, x + r, y + h);
    s.lineTo(x + w - r, y + h);
    s.quadraticCurveTo(x + w, y + h, x + w, y + h - r);
    s.lineTo(x + w, y + r);
    s.quadraticCurveTo(x + w, y, x + w - r, y);
    s.lineTo(x + r, y);
    s.quadraticCurveTo(x, y, x, y + r);
    return s;
  }

  // ---------------- BACKDROP STAGE (never void) ----------------
  const backdropMat = track(new MeshBasicNodeMaterial());
  backdropMat.colorNode = mix(color(stops[1].hex), color(stops[0].hex), uv().y);
  const backdrop = new Mesh(track(new PlaneGeometry(7, 6)), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // Node-local grazing lights so the hairline grid catches specular
  const graze = new DirectionalLight(C_PAPER, 0.55);
  graze.position.set(5, 3.5, 1.2);
  root.add(graze);
  const rim = new DirectionalLight(C_ACCENT, 0.45);
  rim.position.set(-5, 2.5, 1.5);
  root.add(rim);

  // ---------------- CONTENT GROUP (fades up on mount) ----------------
  const content = new Group();
  root.add(content);

  // ---------------- PANEL 3.2 x 2.2, r=0.06 ----------------
  const panelGeo = track(new ShapeGeometry(roundedRect(3.2, 2.2, 0.06), 24));
  const panelMat = track(new MeshStandardNodeMaterial({ roughness: 0.55, metalness: 0.15 }));
  {
    const p = uv(); // ShapeGeometry uvs == local xy coords
    const r = length(vec2(p.x.div(1.6), p.y.div(1.1)));
    const grad = mix(color('#14141a'), color(C_BG), smoothstep(0.0, 1.15, r));
    // hairline grid, 0.25 pitch, 0.006 lines
    const gx = abs(fract(p.x.mul(4.0)).sub(0.5));
    const gy = abs(fract(p.y.mul(4.0)).sub(0.5));
    const lineX = smoothstep(float(0.476), float(0.5), gx);
    const lineY = smoothstep(float(0.476), float(0.5), gy);
    const grid = max(lineX, lineY).mul(0.06);
    let col = mix(grad, color(C_PAPER), grid);
    // hairline border #26262f
    const bx = smoothstep(float(1.592), float(1.6), abs(p.x));
    const by = smoothstep(float(1.092), float(1.1), abs(p.y));
    col = mix(col, color('#26262f'), max(bx, by));
    panelMat.colorNode = col;
  }
  const panel = new Mesh(panelGeo, panelMat);
  content.add(panel);

  // ---------------- GHOST PREVIEW (left of center) ----------------
  const ghost = new Group();
  ghost.position.set(-0.9, 0.05, 0.02);
  content.add(ghost);

  const ghostStrokeMat = track(new MeshBasicNodeMaterial({ transparent: true, opacity: 0.3 }));
  ghostStrokeMat.colorNode = color(C_PAPER);
  const ghostBarMat = track(new MeshBasicNodeMaterial({ transparent: true, opacity: 0.22 }));
  ghostBarMat.colorNode = color(C_PAPER);
  ghostStrokeMat.userData.base = 0.3;
  ghostBarMat.userData.base = 0.22;

  const hGeo = track(new PlaneGeometry(1.1, 0.008));
  const vGeo = track(new PlaneGeometry(0.008, 1.4));
  const top = new Mesh(hGeo, ghostStrokeMat); top.position.set(0, 0.7, 0);
  const bot = new Mesh(hGeo, ghostStrokeMat); bot.position.set(0, -0.7, 0);
  const lef = new Mesh(vGeo, ghostStrokeMat); lef.position.set(-0.55, 0, 0);
  const rig = new Mesh(vGeo, ghostStrokeMat); rig.position.set(0.55, 0, 0);
  ghost.add(top, bot, lef, rig);

  const dialGeo = track(new RingGeometry(0.267, 0.275, 56));
  const dial = new Mesh(dialGeo, ghostStrokeMat);
  dial.position.set(0, 0.25, 0);
  ghost.add(dial);

  const barGeo = track(new PlaneGeometry(0.7, 0.06));
  const bar1 = new Mesh(barGeo, ghostBarMat); bar1.position.set(0, -0.32, 0);
  const bar2 = new Mesh(barGeo, ghostBarMat); bar2.position.set(0, -0.48, 0);
  ghost.add(bar1, bar2);

  // ---------------- COPY COLUMN (right of ghost, 0.5 padding) ----------------
  const headline = ctx.fontAtlas.createText(headlineTxt, {
    fontSize: 34, color: C_PAPER, align: 'left', maxWidthPx: 260,
  });
  headline.position.set(0.15, 0.62, 0.03);
  content.add(headline);

  const body = ctx.fontAtlas.createText(bodyTxt, {
    fontSize: 13, color: C_PAPER, align: 'left', maxWidthPx: 250,
  });
  body.position.set(0.15, 0.22, 0.03);
  content.add(body);

  // ---------------- ACCENT CTA (extruded, 1.5 x 0.36) ----------------
  const ctaGeo = track(new ExtrudeGeometry(roundedRect(1.5, 0.36, 0.05), {
    depth: 0.05, bevelEnabled: true, bevelThickness: 0.008, bevelSize: 0.008, bevelSegments: 2, curveSegments: 12,
  }));
  const ctaMat = track(new MeshStandardNodeMaterial({ roughness: 0.5, metalness: 0.2 }));
  {
    const y = positionLocal.y;
    ctaMat.colorNode = mix(color('#c1121f'), color('#ff4450'), smoothstep(float(-0.18), float(0.18), y));
    const ex = smoothstep(float(0.64), float(0.745), abs(positionLocal.x));
    const ey = smoothstep(float(0.125), float(0.178), abs(y));
    ctaMat.emissiveNode = color(C_ACCENT).mul(max(ex, ey).mul(1.5));
  }
  const cta = new Group();
  cta.position.set(0.82, -0.6, 0.03);
  const ctaMesh = new Mesh(ctaGeo, ctaMat);
  cta.add(ctaMesh);

  const ctaLabel = ctx.fontAtlas.createText(ctaTxt, {
    fontSize: 13, color: C_INK, align: 'center', letterSpacingPx: 1,
  });
  ctaLabel.position.set(0, 0, 0.075);
  cta.add(ctaLabel);
  content.add(cta);

  // ---------------- FOREGROUND ACCENT (third depth plane) ----------------
  const tickMat = track(new MeshBasicNodeMaterial());
  tickMat.colorNode = color(C_ACCENT);
  const tick = new Mesh(track(new PlaneGeometry(0.16, 0.014)), tickMat);
  tick.position.set(-1.35, -1.02, 0.45);
  root.add(tick);

  // ---------------- MOUNT: fade-up 0->1, y +0.2 -> 0, 500ms ----------------
  const fadeMats = [];
  content.traverse((o) => {
    if (o.isMesh && o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      for (const m of mats) {
        if (fadeMats.indexOf(m) !== -1) continue;
        if (m.userData.base === undefined) m.userData.base = m.opacity !== undefined ? m.opacity : 1;
        m.transparent = true;
        m.opacity = 0;
        fadeMats.push(m);
      }
    }
  });
  content.position.y = 0.2;

  const fadeProxy = { t: 0 };
  tweens.push(gsap.to(content.position, { y: 0, duration: 0.5, ease: 'power2.out' }));
  tweens.push(gsap.to(fadeProxy, {
    t: 1, duration: 0.5, ease: 'power2.out',
    onUpdate: () => { for (const m of fadeMats) m.opacity = m.userData.base * fadeProxy.t; },
    onComplete: () => {
      // ghost breathing 0.24 -> 0.34, 2400ms, sine yoyo
      const breath = { v: 0.24 };
      tweens.push(gsap.to(breath, {
        v: 0.34, duration: 2.4, ease: 'sine.inOut', yoyo: true, repeat: -1,
        onUpdate: () => {
          ghostStrokeMat.opacity = breath.v;
          ghostBarMat.opacity = breath.v * 0.73;
        },
      }));
    },
  }));

  // ---------------- PRIMITIVES (none specified, apply if present) ----------------
  const prims = config.cinematicPrimitives || [];
  for (const p of prims) {
    if (ctx.primitives[p.name]) primHandles.push(ctx.primitives[p.name](root, p.params));
  }

  // ---------------- INTERACTION ----------------
  root.userData.handlers = {
    click: () => {
      tweens.push(gsap.to(cta.scale, {
        x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)',
        yoyo: true, repeat: 1,
        onComplete: () => ctx.emit('navigate', { to: 'hub-collection' }),
      }));
    },
    hover: () => {
      tweens.push(gsap.to(content.rotation, { y: 0.05, x: -0.02, duration: 0.3, ease: 'power2.out' }));
    },
    unhover: () => {
      tweens.push(gsap.to(content.rotation, { y: 0, x: 0, duration: 0.3, ease: 'power2.out' }));
    },
  };

  // ---------------- CLEANUP ----------------
  root.userData.cleanup = () => {
    for (const t of tweens) t.kill();
    for (const h of primHandles) { if (h && h.cleanup) h.cleanup(); if (h && h.timeline) h.timeline.kill(); }
    for (const d of disposables) { if (d.dispose) d.dispose(); }
    root.traverse((o) => {
      if (o.isMesh) {
        if (o.geometry && disposables.indexOf(o.geometry) === -1) o.geometry.dispose();
        const mats = Array.isArray(o.material) ? o.material : [o.material];
        for (const m of mats) { if (m && m.dispose && disposables.indexOf(m) === -1) m.dispose(); }
      }
    });
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
